local M = class("PetardShopView",LikeOO.OOPopBase)

M.m_uiName = "PetardActivity/PetardShop"  -- prefab name
M.m_size_type = 1
M.m_iphoneXAdapter = true

function M:onEnter()
    EventDispatcher:registerEvent("petardActivity_everyDayEvent", {self, self.everyDayRefreshEvent})
    self:bindUI()
    self:refreshUI()
    self.m_attr_node = GameUtil:commonAttrNode(self.m_control, {mode = 1})
    self:showAniNode()
end

function M:showAniNode()
    local petard_Ani = self:findGameObject("hero_spine")
    GameUtil:updateSpineLoadSet(petard_Ani, "RoleSpine/" .. "zhaocaimao_SkeletonData", "idle", 0, true)
end

function M:everyDayRefreshEvent(event, data)
    -- 刷新
    self.m_model:refreshData(data[self.m_model.m_openId])
    self:refreshUI()
end

function M:bindUI()
    self:setTextByLanKey("close_title_text", self.m_model.m_xlsxActivity.name)
    RedPointUtil:saveLocalRedPointFreshTime("petardShop_everyDayRedDot")
end

function M:refreshUI()
    self:refreshActivityTimer()
    self:refreshLeftNode()
    for index = 1, 6 do
        self:refreshShopItem(index)
    end
    self:refreshTitle()
end

function M:refreshTitle()
    local m_rebateMoneyData = self.m_model.m_rebateMoneyData
    local maxCount = #m_rebateMoneyData
    if m_rebateMoneyData[maxCount] then
        local itemData = m_rebateMoneyData[maxCount]
        self:setTextByLanKey("text_maxCount", itemData.return_count)
    end
end

function M:refreshLeftNode()
    local rebateCount, curId = self.m_model:getRebateMoneyAndLastId()
    self:setTextByLanKey("text_returnMoneyText1", "petard_text_0006")    
    self:setTextByLanKey("text_returnMoneyText2", rebateCount)
    local isShowHint = (curId >= 0)
    if isShowHint then
        local lastHintData = self.m_model.m_rebateMoneyData[(curId + 1)] or {}
        if lastHintData then
            local offsetCount = (lastHintData.count - self.m_model.m_consume)
            self:setTextByLanKey("text_hintText1", "petard_text_0007", offsetCount)
            local offsetMoney = lastHintData.return_count - rebateCount
            self:setTextByLanKey("text_hintText2", "petard_text_0019", offsetMoney)
        end
    end
    self:setObjectVisible("text_hintText1", isShowHint)
    self:setObjectVisible("text_hintText2", isShowHint)
end

function M:refreshShopItem(index)
    local itemObj = self:findGameObject("itemNode"..index)
    if IsNull(itemObj) then
        return
    end
    local luaBehaviour = UIUtil.findLuaBehaviour(itemObj)
    if not luaBehaviour then
        return
    end
    local allShopDatas = self.m_model.m_allShopDatas
    -- 奖励
    local transform = itemObj.transform
    local curGiftData = allShopDatas[index]
    local xlsxData = curGiftData.xlsxData
    local awardData = xlsxData.reward[1]
    local reward_node = UIUtil.findRectTransform(transform, "awardNode")
    UIUtil.destroyAllChild(reward_node)
    if awardData then
        local itemNode = GameUtil:createItemElement(awardData, true, true)
        itemNode.transform:SetParent(reward_node.transform, false)
    end
    local discountValue = math.floor(xlsxData.return_per * 10)
    LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_discountText", "petard_text_0017", discountValue)
    
    if curGiftData.isCanBuy then
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_buyText", xlsxData.price)
    else
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_gotText", "petard_text_0018")
    end
    LuaBehaviourUtil.setObjectVisible(luaBehaviour, "buyNode", curGiftData.isCanBuy)
    LuaBehaviourUtil.setObjectVisible(luaBehaviour, "gotNode", (not curGiftData.isCanBuy))

    -- 按钮
    local btn_buyBtn = luaBehaviour:FindGameObject("btn_buyBtn"..index)
    UIUtil.setButtonClick(
            btn_buyBtn.transform,
            function()
                if not curGiftData.isCanBuy then
                    return
                end
                self:updateMsg("btn_buyBtn", {version = self.m_model.m_version, pos = index, price = xlsxData.price})
            end
    )
end

function M:refreshActivityTimer()
    local startTimer = self.m_model.m_activityData.start_ts
    local endTimer = self.m_model.m_activityData.end_ts
    local starT = TimeUtil.gmTime(startTimer)
    local endT = TimeUtil.gmTime(endTimer)
    local timerFormat = Language:getTextByKey("castingSword_str_0012", starT.year, starT.month, starT.day,
            endT.year, endT.month, endT.day)
    self:setTextByLanKey("text_timer", "castingSword_str_0011", timerFormat)
end

function M:destroy()
    if self.m_attr_node then
        self.m_attr_node:destroy()
        self.m_attr_node = nil
    end
    EventDispatcher:dipatchEvent("petardMainRedDotRefresh")
    EventDispatcher:unRegisterEvent("petardActivity_everyDayEvent", {self, self.everyDayRefreshEvent})
    M.super.destroy(self)
end

return M